function d_traffic_ca(P,R){var L=P.L||60,cars=[],n=P.cars||20;for(var i=0;i<n;i++)cars.push({x:Math.floor(R()*L),v:Math.floor(R()*3)});cars.sort(function(a,b){return a.x-b.x;});var ST=P.steps||10;for(var s=0;s<ST;s++){cars.forEach(function(c,idx){var ahead=cars[(idx+1)%n];var gap=(ahead.x-c.x-1+L)%L;c.v=Math.min(c.v+1,3,Math.max(0,gap));if(R()<0.2)c.v=Math.max(0,c.v-1);c.x=(c.x+c.v)%L;});}var flow=cars.reduce(function(a,c){return a+c.v;},0)/(P.steps||10);return{cars:n,avg_flow_per_step:+flow.toFixed(2),model:'Nagel-Schreckenberg'};}

